        'tags_heading' => 'Étiquettes',
        'tags_intro' => 'Libellés pour les thèmes transversaux — p. ex. Sécurité, ISO, Environnement. Une tâche peut porter un nombre illimité d\'étiquettes. Utilisez les options d\'affichage ci-dessous pour choisir où elles apparaissent.',
        'tags_display_heading' => 'Options d\'affichage',
